import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import java.lang.reflect.Field;
import java.lang.reflect.Proxy;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.EnumSet;
import java.util.List;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.stream.Collectors;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.MenuAction;
import net.runelite.api.WorldType;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.ui.overlay.OverlayMenuEntry;
import net.runelite.http.api.RuneLiteAPI;
import org.junit.Test;

/** "Hide" on the Next step box (new in 0.4.1): it only unticks a setting and says so in chat. */
public class NextStepHideTest
{
	private static final IronwiseConfig DEFAULTS = new IronwiseConfig()
	{
	};

	/** A Client that records chat lines and fails on anything else, so Hide can't act in the game. */
	private static Client chatOnly(List<Object[]> chat)
	{
		return (Client) Proxy.newProxyInstance(Client.class.getClassLoader(), new Class<?>[]{Client.class}, (proxy, method, args) ->
		{
			if ("addChatMessage".equals(method.getName()) && args != null && args.length == 4)
			{
				chat.add(args);
				return null;
			}
			throw new AssertionError("Hide called Client." + method.getName());
		});
	}

	@Test
	public void theBoxHasAHideEntry()
	{
		NextStepOverlay overlay = new NextStepOverlay(new IronwisePlugin(), null, DEFAULTS, new GuideState());
		List<OverlayMenuEntry> entries = overlay.getMenuEntries();
		assertEquals("Hide", NextStepOverlay.HIDE);
		assertEquals(3, entries.size());
		assertEquals(
			Arrays.asList(NextStepOverlay.MARK_DONE, NextStepOverlay.SKIP, NextStepOverlay.HIDE),
			entries.stream().map(OverlayMenuEntry::getOption).collect(Collectors.toList()));
		// All three are RuneLite overlay entries (Shift + right-click on the box), not game menu options.
		for (OverlayMenuEntry e : entries)
		{
			assertEquals(e.getOption(), MenuAction.RUNELITE_OVERLAY, e.getMenuAction());
			assertEquals(e.getOption(), "Next step", e.getTarget());
		}
	}

	@Test
	public void hidingUnticksShowNextStepAndSaysHowToGetItBack()
	{
		List<Object[]> writes = new ArrayList<>();
		List<Object[]> chat = new ArrayList<>();
		NextStepOverlay.hide((group, key, value) -> writes.add(new Object[]{group, key, value}), chatOnly(chat));

		assertEquals(1, writes.size());
		assertArrayEquals(new Object[]{"ironwise", "showNextStep", false}, writes.get(0));
		assertEquals(1, chat.size());
		assertArrayEquals(new Object[]{ChatMessageType.GAMEMESSAGE, "",
			"Ironwise: Next step box hidden. Tick Show next guide step in the Ironwise settings to bring it back.", null}, chat.get(0));
	}

	@Test
	public void theSettingHideWritesIsTheBoxsSetting() throws NoSuchMethodException
	{
		// The group and key the settings panel uses for "Show next guide step", and the name the chat line gives.
		assertEquals(IronwiseConfig.class.getAnnotation(ConfigGroup.class).value(), IronwiseConfig.GROUP);
		ConfigItem item = IronwiseConfig.class.getMethod("showNextStep").getAnnotation(ConfigItem.class);
		assertEquals(item.keyName(), IronwiseConfig.SHOW_NEXT_STEP);
		assertTrue(NextStepOverlay.HIDDEN.contains("Tick " + item.name() + " in the Ironwise settings"));
		// The description tells players about Hide.
		assertTrue(item.description(), item.description().contains("Hide"));
	}

	@Test
	public void hidingDoesntSyncAgain() throws ReflectiveOperationException
	{
		// Syncing stopped over a setting only the player can fix, and nothing has changed since the last sync.
		IronwisePlugin plugin = new IronwisePlugin();
		set(plugin, "stopped", "Ironwise: paste your device token in the plugin settings.");
		set(plugin, "dirty", false);
		set(plugin, "announced", true);

		ConfigChanged changed = new ConfigChanged();
		changed.setGroup(IronwiseConfig.GROUP);
		changed.setKey(IronwiseConfig.SHOW_NEXT_STEP);
		changed.setOldValue("true");
		changed.setNewValue("false");
		plugin.onConfigChanged(changed);

		// Only the box changed: no new sync, no "syncing" line, and still stopped.
		assertFalse((Boolean) get(plugin, "dirty"));
		assertTrue((Boolean) get(plugin, "announced"));
		assertEquals("Ironwise: paste your device token in the plugin settings.", get(plugin, "stopped"));
	}

	@Test
	public void theBoxDrawsNothingOnceHiddenAndComesBackWithTheSetting()
	{
		// The setting, as RuneLite's ConfigManager would keep it.
		AtomicBoolean shown = new AtomicBoolean(true);
		IronwiseConfig config = new IronwiseConfig()
		{
			@Override
			public boolean syncEnabled()
			{
				return true;
			}

			@Override
			public boolean showNextStep()
			{
				return shown.get();
			}
		};
		GuideState guide = new GuideState();
		guide.synced(guide.session(), "1234567890123456789", 1, NextStep.fromBody(RuneLiteAPI.GSON, "{\"guide\":" + NextStepTest.stepJson() + "}", "guide"));
		assertNotNull(guide.step());
		List<Object[]> chat = new ArrayList<>();
		Client client = loggedIn(chat);
		NextStepOverlay overlay = new NextStepOverlay(new IronwisePlugin(), client, config, guide);
		Graphics2D graphics = new BufferedImage(400, 400, BufferedImage.TYPE_INT_ARGB).createGraphics();

		Dimension before = overlay.render(graphics);
		assertNotNull(before);
		assertTrue(before.height > 0);

		NextStepOverlay.hide((group, key, value) ->
		{
			if (IronwiseConfig.GROUP.equals(group) && IronwiseConfig.SHOW_NEXT_STEP.equals(key))
			{
				shown.set(value);
			}
		}, client);
		assertFalse(shown.get());
		assertNull(overlay.render(graphics));
		// Hide didn't forget the step: ticking the setting again shows it at once.
		assertNotNull(guide.step());
		shown.set(true);
		assertNotNull(overlay.render(graphics));
		assertEquals(1, chat.size());
		graphics.dispose();
	}

	/** A logged-in Client on a standard world that records chat lines and fails on anything else. */
	private static Client loggedIn(List<Object[]> chat)
	{
		return (Client) Proxy.newProxyInstance(Client.class.getClassLoader(), new Class<?>[]{Client.class}, (proxy, method, args) ->
		{
			switch (method.getName())
			{
				case "getGameState":
					return GameState.LOGGED_IN;
				case "getWorldType":
					return EnumSet.noneOf(WorldType.class);
				case "addChatMessage":
					chat.add(args);
					return null;
				default:
					throw new AssertionError("the box called Client." + method.getName());
			}
		});
	}

	private static void set(IronwisePlugin plugin, String name, Object value) throws ReflectiveOperationException
	{
		Field f = IronwisePlugin.class.getDeclaredField(name);
		f.setAccessible(true);
		f.set(plugin, value);
	}

	private static Object get(IronwisePlugin plugin, String name) throws ReflectiveOperationException
	{
		Field f = IronwisePlugin.class.getDeclaredField(name);
		f.setAccessible(true);
		return f.get(plugin);
	}
}

package com.ironwise;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

import com.sun.net.httpserver.HttpServer;
import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.OutputStream;
import java.net.InetAddress;
import java.net.InetSocketAddress;
import java.net.ServerSocket;
import java.net.Socket;
import java.nio.charset.StandardCharsets;
import java.util.List;
import java.util.concurrent.CopyOnWriteArrayList;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicReference;
import net.runelite.http.api.RuneLiteAPI;
import okhttp3.HttpUrl;
import okhttp3.OkHttpClient;
import org.junit.After;
import org.junit.Before;
import org.junit.Test;

/** SyncClient against a real (local) HTTP server: what actually goes over the wire. */
public class SyncClientHttpTest
{
	private static final byte[] OK = "{\"ok\":true,\"rsn\":\"Iron Test\",\"receivedAt\":1}".getBytes(StandardCharsets.UTF_8);

	private HttpServer server;
	private String base;
	/** "path Authorization" for every request the server saw. */
	private final List<String> seen = new CopyOnWriteArrayList<>();
	private final SyncClient client = new SyncClient(new OkHttpClient(), RuneLiteAPI.GSON);

	@Before
	public void start() throws Exception
	{
		server = HttpServer.create(new InetSocketAddress("127.0.0.1", 0), 0);
		server.createContext("/", exchange ->
		{
			String path = exchange.getRequestURI().getPath();
			seen.add(path + " " + exchange.getRequestHeaders().getFirst("Authorization"));
			exchange.getRequestBody().close();
			if ("/ok/api/sync".equals(path))
			{
				exchange.sendResponseHeaders(200, OK.length);
				try (OutputStream out = exchange.getResponseBody())
				{
					out.write(OK);
				}
				return;
			}
			if ("/moved/api/sync".equals(path))
			{
				exchange.getResponseHeaders().add("Location", base + "/elsewhere/api/sync");
			}
			exchange.sendResponseHeaders("/moved/api/sync".equals(path) ? 307 : 404, -1);
			exchange.close();
		});
		server.start();
		base = "http://127.0.0.1:" + server.getAddress().getPort();
	}

	@After
	public void stop()
	{
		server.stop(0);
	}

	private SyncClient.Result send(String address) throws Exception
	{
		HttpUrl url = SyncClient.syncUrl(address);
		assertNotNull(address, url);
		CountDownLatch done = new CountDownLatch(1);
		AtomicReference<SyncClient.Result> result = new AtomicReference<>();
		client.send(url, "iw_test", "{}", r ->
		{
			result.set(r);
			done.countDown();
		});
		assertTrue("no answer in time", done.await(20, TimeUnit.SECONDS));
		return result.get();
	}

	@Test
	public void savedByIronwise() throws Exception
	{
		assertEquals(SyncClient.Outcome.OK, send(base + "/ok").outcome);
		assertEquals("/ok/api/sync Bearer iw_test", seen.get(0));
	}

	@Test
	public void aRedirectIsNotFollowedAndTheTokenStaysPut() throws Exception
	{
		SyncClient.Result r = send(base + "/moved");
		assertEquals(SyncClient.Outcome.WRONG_ADDRESS, r.outcome);
		assertEquals("that address redirects to " + base + "/elsewhere; use that address instead.", r.message);
		// Only the address the player set was asked; the token never went to the redirect's target.
		assertEquals(1, seen.size());
		assertEquals("/moved/api/sync Bearer iw_test", seen.get(0));
	}

	@Test
	public void aCutOffAnswerIsRetriedNotAWrongAddress() throws Exception
	{
		// A server that promises Ironwise's whole answer, sends a few bytes of it, then hangs up.
		try (ServerSocket cut = new ServerSocket(0, 1, InetAddress.getByName("127.0.0.1")))
		{
			Thread t = new Thread(() ->
			{
				try (Socket s = cut.accept())
				{
					BufferedReader in = new BufferedReader(new InputStreamReader(s.getInputStream(), StandardCharsets.UTF_8));
					String line;
					while ((line = in.readLine()) != null && !line.isEmpty())
					{
						// skip the request headers
					}
					OutputStream out = s.getOutputStream();
					out.write(("HTTP/1.1 200 OK\r\nContent-Type: application/json\r\nContent-Length: " + OK.length + "\r\n\r\n").getBytes(StandardCharsets.UTF_8));
					out.write(OK, 0, 5);
					out.flush();
				}
				catch (Exception e)
				{
					// the test fails on the result instead
				}
			});
			t.start();
			SyncClient.Result r = send("http://127.0.0.1:" + cut.getLocalPort());
			t.join(5000);
			assertEquals(r.message, SyncClient.Outcome.RETRY, r.outcome);
			assertTrue(r.message, r.message.startsWith("couldn't read the app's answer"));
		}
	}
}

package com.ironwise;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
