import org.junit.Test;

/** The JSON the plugin posts, as RuneLite's own Gson writes it. Made-up data only. */
public class SyncPayloadTest
{
	/** The Gson RuneLite injects into plugins. */
	private static final Gson GSON = RuneLiteAPI.GSON;

	private static SyncPayload payload()
	{
		SyncPayload p = new SyncPayload();
		p.plugin = IronwisePlugin.VERSION;
		p.sentAt = 1790243320266L;
		p.account = new SyncPayload.Account("1234567890123456789", "Iron Example", 302);
		p.skills = Collections.emptyMap();
		p.containers = Collections.emptyMap();
		p.varbits = Collections.emptyMap();
		p.varps = Collections.emptyMap();
		p.saved = Collections.emptyMap();
		return p;
	}

	@Test
	public void noCollectionLogKeyUntilSomethingIsKnown()
	{
		JsonObject json = new JsonParser().parse(GSON.toJson(payload())).getAsJsonObject();
		assertFalse(json.has("collectionLog"));
		assertEquals(1, json.get("v").getAsInt());
		assertEquals(IronwisePlugin.VERSION, json.get("plugin").getAsString());
	}

	@Test
	public void collectionLogShape()
	{
		CollectionLogState state = new CollectionLogState();
		state.searchSeen(Collections.singletonMap(22006, 1), 1000);
		state.pageSeen("Vorkath", Collections.singletonMap("Vorkath kills", 61), Arrays.asList(11286, 22006),
			Collections.singletonMap(11286, 2), 2000);
		state.added("Vorkath's head", 3000);
		SyncPayload p = payload();
		p.collectionLog = state.toPayload();

		JsonObject log = new JsonParser().parse(GSON.toJson(p)).getAsJsonObject().getAsJsonObject("collectionLog");
		assertEquals("{\"seenAt\":1000,\"items\":[[22006,1]]}", log.get("all").toString());
		assertEquals("{\"Vorkath\":{\"seenAt\":2000,\"kc\":[[\"Vorkath kills\",61]],\"items\":[[11286,2],[22006,1]]}}", log.get("pages").toString());
		assertEquals("[[\"Vorkath's head\",3000]]", log.get("added").toString());
	}

	@Test
	public void pagesAndAddedArePresentWhenOnlyOneIsKnown()
	{
		CollectionLogState state = new CollectionLogState();
		state.added("Vorkath's head", 3000);
		SyncPayload p = payload();
		p.collectionLog = state.toPayload();

		JsonObject log = new JsonParser().parse(GSON.toJson(p)).getAsJsonObject().getAsJsonObject("collectionLog");
		assertFalse(log.has("all"));
		assertEquals("{}", log.get("pages").toString());
		JsonArray added = log.getAsJsonArray("added");
		assertEquals(1, added.size());
	}

	@Test
	public void trackedVarsIncludeSpellbookAndCombatAchievements()
	{
		Set<Integer> varbits = new HashSet<>();
		for (int id : TrackedVars.VARBITS)
		{
			assertTrue("duplicate varbit " + id, varbits.add(id));
		}
		Set<Integer> varps = new HashSet<>();
		for (int id : TrackedVars.VARPS)
		{
			assertTrue("duplicate varp " + id, varps.add(id));
		}
		assertEquals(4070, VarbitID.SPELLBOOK);
		assertTrue(varbits.contains(VarbitID.SPELLBOOK));
		int[] ca = {
			VarPlayerID.CA_TASK_COMPLETED_0, VarPlayerID.CA_TASK_COMPLETED_1, VarPlayerID.CA_TASK_COMPLETED_2,
			VarPlayerID.CA_TASK_COMPLETED_3, VarPlayerID.CA_TASK_COMPLETED_4, VarPlayerID.CA_TASK_COMPLETED_5,
			VarPlayerID.CA_TASK_COMPLETED_6, VarPlayerID.CA_TASK_COMPLETED_7, VarPlayerID.CA_TASK_COMPLETED_8,
			VarPlayerID.CA_TASK_COMPLETED_9, VarPlayerID.CA_TASK_COMPLETED_10, VarPlayerID.CA_TASK_COMPLETED_11,
			VarPlayerID.CA_TASK_COMPLETED_12, VarPlayerID.CA_TASK_COMPLETED_13, VarPlayerID.CA_TASK_COMPLETED_14,
			VarPlayerID.CA_TASK_COMPLETED_15, VarPlayerID.CA_TASK_COMPLETED_16, VarPlayerID.CA_TASK_COMPLETED_17,
			VarPlayerID.CA_TASK_COMPLETED_18, VarPlayerID.CA_TASK_COMPLETED_19, VarPlayerID.CA_TASK_COMPLETED_20,
		};
		for (int id : ca)
		{
			assertTrue("missing CA varp " + id, varps.contains(id));
		}
		// The ids the app expects (RuneLite gameval, runelite-parent-1.12.39).
		assertEquals(3116, VarPlayerID.CA_TASK_COMPLETED_0);
		assertEquals(3128, VarPlayerID.CA_TASK_COMPLETED_12);
		assertEquals(3387, VarPlayerID.CA_TASK_COMPLETED_13);
		assertEquals(5673, VarPlayerID.CA_TASK_COMPLETED_20);
	}
}

package com.ironwise;

import com.google.gson.Gson;
import java.io.IOException;
import javax.inject.Inject;
import javax.inject.Singleton;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.HttpUrl;
import okhttp3.MediaType;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;
import okhttp3.Response;
import okhttp3.ResponseBody;

/** Posts syncs to Ironwise on OkHttp's thread pool (never the client thread). */
@Singleton
class SyncClient
{
	static final MediaType JSON = MediaType.parse("application/json; charset=utf-8");

	static final String NOT_IRONWISE = "that address answered, but it isn't the Ironwise app.";
	static final String LOGIN = "that address asked for a login. It isn't the Ironwise app, or it's a Vercel deployment URL: use the app's main address.";
	static final String NO_APP = "there's no Ironwise app at that address. Check it in the plugin settings.";
	static final String BAD_TOKEN = "this token isn't recognised. Make a new one on the app's Live data page.";
	static final String TOO_BIG = "it's too big.";

	interface Listener
	{
		void done(Result result);
	}

	enum Outcome
	{
		/** Saved. */
		OK,
		/** Ironwise doesn't know the token. */
		UNAUTHORIZED,
		/** The address isn't the Ironwise app (another site, a login page, a redirect). */
		WRONG_ADDRESS,
		/** Ironwise refused the data (e.g. it needs a newer plugin). */
		REJECTED,
		/** Couldn't reach Ironwise, or it had a problem: try again later. */
		RETRY,
	}

	static final class Result
	{
		final Outcome outcome;
		final String message;
		/** What a saved sync's answer said about the guide's next step (new in 0.4.0). */
		final NextStep.Reply guide;

		Result(Outcome outcome, String message)
		{
			this(outcome, message, NextStep.Reply.NOTHING);
		}

		Result(Outcome outcome, String message, NextStep.Reply guide)
		{
			this.outcome = outcome;
			this.message = message;
			this.guide = guide;
		}
	}

	/** Every answer from Ironwise's /api/sync: { "ok": true|false, "message": "..." }. */
	private static final class Body
	{
		Boolean ok;
		String message;
	}

	/** RuneLite's client, but redirects come back to us: a token must only go to the address the player set. */
	final OkHttpClient http;
	private final Gson gson;

	@Inject
	SyncClient(OkHttpClient http, Gson gson)
	{
		this.http = http.newBuilder().followRedirects(false).followSslRedirects(false).build();
		this.gson = gson;
	}

	/**
	 * The sync endpoint for an Ironwise address, or null if the address isn't usable. HTTPS only,
	 * except on this computer (http://localhost while running Ironwise locally).
	 */
	static HttpUrl syncUrl(String address)
	{
		return appUrl(address, "/api/sync");
	}

	/** {@code path} ("/api/...") on an Ironwise address, with the same rules as {@link #syncUrl}. */
	static HttpUrl appUrl(String address, String path)
	{
		if (address == null)
		{
			return null;
		}
		String a = address.trim();
		while (a.endsWith("/"))
		{
			a = a.substring(0, a.length() - 1);
		}
		if (a.isEmpty())
		{
			return null;
		}
		if (!a.contains("://"))
		{
			a = "https://" + a;
		}
		HttpUrl base = HttpUrl.parse(a);
		if (base == null)
		{
			return null;
		}
		boolean local = "localhost".equals(base.host()) || "127.0.0.1".equals(base.host()) || "[::1]".equals(base.host()) || "::1".equals(base.host());
		if (!"https".equals(base.scheme()) && !local)
		{
			return null;
		}
		return HttpUrl.parse(a + path);
	}

	/** A JSON post to Ironwise with the device token. */
	static Request post(HttpUrl url, String token, String json)
	{
		return new Request.Builder()
			.url(url)
			.header("Authorization", "Bearer " + token)
			.header("User-Agent", "Ironwise-RuneLite/" + IronwisePlugin.VERSION)
			.post(RequestBody.create(JSON, json))
			.build();
	}

	void send(HttpUrl url, String token, String json, Listener listener)
	{
		http.newCall(post(url, token, json)).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				listener.done(new Result(Outcome.RETRY, "can't reach the app (" + e.getMessage() + ")"));
			}

			@Override
			public void onResponse(Call call, Response response)
			{
				Result r;
				try
				{
					r = result(response.code(), bodyOf(response), redirectOf(response));
				}
				catch (IOException e)
				{
					// The answer was cut off, so we can't tell what it said: try again, don't stop.
					r = new Result(Outcome.RETRY, "couldn't read the app's answer (" + e.getMessage() + ")");
				}
				catch (RuntimeException e)
				{
					r = new Result(Outcome.RETRY, "unexpected answer from the app");
				}
				finally
				{
					response.close();
				}
				listener.done(r);
			}
		});
	}

	static String bodyOf(Response response) throws IOException
	{
		ResponseBody body = response.body();
		return body == null ? "" : body.string();
	}

	/** Where a redirect points, relative to the address we posted to; null if it isn't a redirect. */
	private static HttpUrl redirectOf(Response response)
	{
		String location = response.header("Location");
		return response.isRedirect() && location != null ? response.request().url().resolve(location) : null;
	}

	/** Ironwise's JSON answer, or null if the body is something else (a web page, another app). */
	private Body ironwise(String body)
	{
		try
		{
			Body b = gson.fromJson(body, Body.class);
			return b != null && b.ok != null ? b : null;
		}
		catch (RuntimeException e)
		{
			return null;
		}
	}

	Result result(int code, String body, HttpUrl redirect)
	{
		Body b = ironwise(body);
		String message = b != null && b.message != null && !b.message.trim().isEmpty() ? b.message.trim() : null;
		if (code >= 200 && code < 300)
		{
			return b != null && b.ok
				? new Result(Outcome.OK, null, NextStep.fromBody(gson, body, "guide"))
				: new Result(Outcome.WRONG_ADDRESS, NOT_IRONWISE);
		}
		if (code >= 300 && code < 400)
		{
			return new Result(Outcome.WRONG_ADDRESS, redirected(redirect));
		}
		if (code == 401 || code == 403)
		{
			if (b == null)
			{
				return new Result(Outcome.WRONG_ADDRESS, LOGIN);
			}
			return new Result(Outcome.UNAUTHORIZED, message != null ? message : BAD_TOKEN);
		}
		if (code == 404)
		{
			return new Result(Outcome.REJECTED, NO_APP);
		}
		if (code == 400 || code == 413)
		{
			return new Result(Outcome.REJECTED, message != null ? message : code == 413 ? TOO_BIG : "the app answered " + code);
		}
		return new Result(Outcome.RETRY, message != null ? message : "the app answered " + code);
	}

	/**
	 * What to say about a redirect. Ironwise's sync address never redirects, so the player's address is
	 * wrong: if it leads to another sync address (www., https), that's the one to use; anywhere else is a
	 * login or another site.
	 */
	static String redirected(HttpUrl to)
	{
		if (to == null)
		{
			return "that address redirects somewhere else. Use the app's main address.";
		}
		String url = to.newBuilder().query(null).fragment(null).build().toString();
		if (url.endsWith("/api/sync"))
		{
			String address = url.substring(0, url.length() - "/api/sync".length());
			if (syncUrl(address) != null)
			{
				return "that address redirects to " + address + "; use that address instead.";
			}
		}
		return "that address redirects to " + to.host() + ", which isn't the Ironwise app. If it's a Vercel deployment URL, use the app's main address.";
	}
}

package com.ironwise;

import com.google.gson.Gson;
import com.google.inject.Provides;
import java.util.Arrays;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import javax.inject.Inject;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.events.AccountHashChanged;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.events.ScriptPreFired;
import net.runelite.api.events.StatChanged;
import net.runelite.api.events.VarbitChanged;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.config.RuneScapeProfileType;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;
import okhttp3.HttpUrl;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

@PluginDescriptor(
	name = "Ironwise",
	description = "Syncs your account to Ironwise, a private invite-only Ironman planner, and shows your next guide step",
	tags = {"ironman", "sync", "planner", "progress", "bank", "clog", "guide", "companion"}
)
public class IronwisePlugin extends Plugin
{
	static final String VERSION = "0.4.1";

	private static final Logger log = LoggerFactory.getLogger(IronwisePlugin.class);

	/** Let the game settle after login before reading variables. */
	private static final int LOGIN_SETTLE_TICKS = 5;
	/** At most one sync per 30 seconds while things change. */
	private static final long MIN_INTERVAL_MS = 30_000L;
	/** Send anyway every 10 minutes while logged in, so Ironwise can show the account as live. */
	private static final long HEARTBEAT_MS = 10 * 60_000L;
	/** Waits after failures: 1, 2, 4, 8, then 15 minutes. */
	private static final long MAX_BACKOFF_MS = 15 * 60_000L;

	private static final Set<Integer> VARBITS = new HashSet<>();
	private static final Set<Integer> VARPS = new HashSet<>();

	static
	{
		Arrays.stream(TrackedVars.VARBITS).forEach(VARBITS::add);
		Arrays.stream(TrackedVars.VARPS).forEach(VARPS::add);
	}

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private IronwiseConfig config;

	@Inject
	private PayloadBuilder builder;

	@Inject
	private SyncClient syncClient;

	@Inject
	private CollectionLogState collectionLog;

	@Inject
	private CollectionLogReader collectionLogReader;

	@Inject
	private Gson gson;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private NextStepOverlay nextStepOverlay;

	@Inject
	private GuideState guide;

	@Inject
	private GuideClient guideClient;

	@Inject
	private ConfigManager configManager;

	private int ticksLoggedIn;
	private boolean dirty;
	private long lastAttemptAt;
	private long nextAttemptAt;
	private long backoffMs;
	private int failures;
	private String lastSentSignature;
	private long lastSentAt;
	private boolean announced;
	/** A problem only the player can fix (token, address, plugin version): wait for a settings change. */
	private String stopped;
	private volatile boolean inFlight;

	/** The clock (a method so tests can move time on). */
	long now()
	{
		return System.currentTimeMillis();
	}

	@Provides
	IronwiseConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(IronwiseConfig.class);
	}

	@Override
	protected void startUp()
	{
		resetSession();
		overlayManager.add(nextStepOverlay);
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(nextStepOverlay);
		resetSession();
	}

	private void resetSession()
	{
		builder.reset();
		collectionLogReader.reset();
		guide.clear();
		ticksLoggedIn = 0;
		dirty = true;
		lastSentSignature = null;
		lastSentAt = 0;
		announced = false;
		stopped = null;
		clearBackoff();
	}

	private void clearBackoff()
	{
		nextAttemptAt = 0;
		backoffMs = 0;
		failures = 0;
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOGGED_IN)
		{
			dirty = true;
		}
		else if (event.getGameState() == GameState.LOGIN_SCREEN || event.getGameState() == GameState.HOPPING)
		{
			ticksLoggedIn = 0;
			collectionLogReader.reset();
			if (event.getGameState() == GameState.LOGIN_SCREEN)
			{
				// Logged out: the next login may be another account.
				guide.clear();
			}
		}
	}

	@Subscribe
	public void onAccountHashChanged(AccountHashChanged event)
	{
		builder.reset();
		collectionLogReader.reset();
		guide.clear();
		lastSentSignature = null;
		announced = false;
		dirty = true;
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		if (PayloadBuilder.isTrackedContainer(event.getContainerId()))
		{
			builder.onContainerChanged(event.getContainerId(), event.getItemContainer(), now());
			dirty = true;
		}
	}

	@Subscribe
	public void onStatChanged(StatChanged event)
	{
		dirty = true;
	}

	@Subscribe
	public void onVarbitChanged(VarbitChanged event)
	{
		if (event.getVarpId() == VarPlayerID.QP)
		{
			builder.questsChanged();
		}
		if (VARBITS.contains(event.getVarbitId()) || VARPS.contains(event.getVarpId()))
		{
			dirty = true;
		}
	}

	@Subscribe
	public void onScriptPreFired(ScriptPreFired event)
	{
		collectionLogReader.onScriptPreFired(event);
	}

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		if (collectionLogReader.onChatMessage(event, now()))
		{
			dirty = true;
		}
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (IronwiseConfig.GROUP.equals(event.getGroup()))
		{
			if (IronwiseConfig.SHOW_NEXT_STEP.equals(event.getKey()))
			{
				// Only the Next step box (its setting, or Hide on the box): nothing about syncing changed,
				// so there's nothing to send again.
				return;
			}
			if (IronwiseConfig.SYNC_COLLECTION_LOG.equals(event.getKey()))
			{
				// Only what's read changed, not where or how to sync. CollectionLogReader checks the setting
				// before every read, on the client thread (this may run on the settings panel's): unticked,
				// it reads nothing more and drops what it read before the next sync is built, which then has
				// no collection log section (Ironwise keeps what it had); ticked, the log is read once the
				// player opens it.
				return;
			}
			if ("serverUrl".equals(event.getKey()) || "token".equals(event.getKey()))
			{
				// Maybe another Ironwise: show no step until it answers.
				guide.clear();
			}
			// New address or token: try again straight away.
			stopped = null;
			lastSentSignature = null;
			announced = false;
			clearBackoff();
			dirty = true;
			return;
		}
		for (String group : PayloadBuilder.SAVED_GROUPS)
		{
			if (group.equals(event.getGroup()))
			{
				dirty = true;
				return;
			}
		}
	}

	@Subscribe
	public void onGameTick(GameTick tick)
	{
		if (client.getGameState() != GameState.LOGGED_IN)
		{
			return;
		}
		// Before the payload is built: with Sync collection log unticked, this drops anything read of the log.
		if (collectionLogReader.onGameTick(now()))
		{
			dirty = true;
		}
		int listed = collectionLogReader.takeFinishedListing();
		if (!config.syncEnabled())
		{
			return;
		}
		if (listed >= 0)
		{
			say("Ironwise: read your collection log (" + listed + " items).");
		}
		if (++ticksLoggedIn < LOGIN_SETTLE_TICKS || stopped != null || inFlight)
		{
			return;
		}
		// Leagues, Deadman, beta and other special worlds aren't your real account.
		if (RuneScapeProfileType.getCurrent(client) != RuneScapeProfileType.STANDARD)
		{
			return;
		}
		long now = now();
		boolean heartbeat = now - lastSentAt >= HEARTBEAT_MS;
		if ((!dirty && !heartbeat) || now < nextAttemptAt || now - lastAttemptAt < MIN_INTERVAL_MS)
		{
			return;
		}

		HttpUrl url = SyncClient.syncUrl(config.serverUrl());
		String token = config.token() == null ? "" : config.token().trim();
		if (url == null || token.isEmpty())
		{
			stop(url == null
				? "Ironwise: set your Ironwise address in the plugin settings (it must start with https://)."
				: "Ironwise: paste your device token in the plugin settings.");
			return;
		}

		SyncPayload payload = builder.build(VERSION, now);
		if (payload == null)
		{
			return;
		}
		dirty = false;
		// Compare without the timestamp: only send when something changed (or for the heartbeat).
		payload.sentAt = 0;
		String signature = gson.toJson(payload);
		if (!heartbeat && signature.equals(lastSentSignature))
		{
			return;
		}
		payload.sentAt = now;
		String json = gson.toJson(payload);
		SyncPayload.Account account = payload.account;
		List<Object[]> added = payload.collectionLog == null ? null : payload.collectionLog.added;
		int session = guide.session();

		lastAttemptAt = now;
		inFlight = true;
		try
		{
			syncClient.send(url, token, json, result -> clientThread.invokeLater(() -> finished(result, signature, now, account, added, session)));
		}
		catch (RuntimeException e)
		{
			finished(new SyncClient.Result(SyncClient.Outcome.RETRY, "couldn't send (" + e.getMessage() + ")"), signature, now, account, added, session);
		}
	}

	/** Back on the client thread after a sync. */
	private void finished(SyncClient.Result result, String signature, long sentAt, SyncPayload.Account account, List<Object[]> added, int session)
	{
		inFlight = false;
		String rsn = account.rsn;
		switch (result.outcome)
		{
			case OK:
				lastSentSignature = signature;
				lastSentAt = sentAt;
				// Ironwise has the "new item" lines now: don't send them again.
				collectionLog.addedSent(added);
				guide.synced(session, account.hash, sentAt, result.guide);
				clearBackoff();
				if (!announced)
				{
					announced = true;
					say("Ironwise: syncing " + rsn + ".");
				}
				break;
			case UNAUTHORIZED:
			case WRONG_ADDRESS:
				stop("Ironwise: " + result.message);
				break;
			case REJECTED:
				stop("Ironwise: the app couldn't use the sync: " + result.message);
				break;
			case RETRY:
			default:
				failures++;
				backoffMs = backoffMs == 0 ? 60_000L : Math.min(backoffMs * 2, MAX_BACKOFF_MS);
				nextAttemptAt = now() + backoffMs;
				dirty = true;
				log.debug("Ironwise sync failed ({}), retrying in {}s", result.message, backoffMs / 1000);
				if (failures == 3)
				{
					say("Ironwise: " + result.message + ". Still trying.");
				}
				break;
		}
	}

	/**
	 * "Mark step done" ({@link GuideClient#DONE}) or "Skip step" ({@link GuideClient#SKIP}) on the Next
	 * step box, on the client thread. Tells Ironwise; its answer's next step replaces the one shown.
	 */
	void guideAction(String action)
	{
		if (!config.syncEnabled())
		{
			return;
		}
		GuideState.Tick tick = guide.startTick(action);
		if (tick == null)
		{
			// Nothing shown, or the last click is still on its way.
			return;
		}
		String what = GuideClient.SKIP.equals(action) ? "skip the step" : "mark the step done";
		HttpUrl url = GuideClient.tickUrl(config.serverUrl());
		String token = config.token() == null ? "" : config.token().trim();
		if (url == null || token.isEmpty())
		{
			ticked(tick, what, GuideClient.Result.failed(url == null
				? "set your Ironwise address in the plugin settings (it must start with https://)."
				: "paste your device token in the plugin settings."));
			return;
		}
		try
		{
			guideClient.send(url, token, tick, result -> clientThread.invokeLater(() -> ticked(tick, what, result)));
		}
		catch (RuntimeException e)
		{
			ticked(tick, what, GuideClient.Result.failed("couldn't send (" + e.getMessage() + ")"));
		}
	}

	/**
	 * "Hide" on the Next step box, on the client thread: unticks Show next guide step and says in chat
	 * how to bring the box back. Nothing is sent to Ironwise.
	 */
	void hideNextStep()
	{
		NextStepOverlay.hide((group, key, value) -> configManager.setConfiguration(group, key, value), client);
	}

	/** Back on the client thread after a mark. */
	private void ticked(GuideState.Tick tick, String what, GuideClient.Result result)
	{
		if (guide.ticked(tick, now(), result.ok, result.next) && !result.ok)
		{
			// The player asked for this, so they hear why it didn't work even with chat messages off.
			client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", "Ironwise: couldn't " + what + ": " + result.message, null);
		}
	}

	private void stop(String message)
	{
		stopped = message;
		// Ironwise stops hearing from this account until the settings change, so the step shown can't
		// follow it any more: hide it rather than leave an old step up.
		guide.clear();
		log.debug(message);
		say(message);
	}

	private void say(String message)
	{
		if (config.chatMessages())
		{
			client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", message, null);
		}
	}
}

package com.ironwise;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup(IronwiseConfig.GROUP)
public interface IronwiseConfig extends Config
{
	String GROUP = "ironwise";
	/** The Ironwise site the plugin's author runs for their group. Players change it only if the site's owner gives them another address. */
	String DEFAULT_ADDRESS = "https://ironwise-eight.vercel.app";

	@ConfigItem(
		keyName = "syncEnabled",
		name = "Sync with Ironwise",
		description = "Send this account's progress (skills, quests, diaries, bank and storage, unlocks, timers and kill counts, and your collection log if Sync collection log is ticked) to your Ironwise app.",
		warning = "This feature submits your IP address to a 3rd-party server not controlled or verified by RuneLite developers",
		position = 0
	)
	default boolean syncEnabled()
	{
		return false;
	}

	@ConfigItem(
		keyName = "serverUrl",
		name = "Ironwise address",
		description = "The Ironwise app to sync with. Keep the default unless you were given another address. It must start with https:// (http:// only works for localhost).",
		position = 1
	)
	default String serverUrl()
	{
		return DEFAULT_ADDRESS;
	}

	@ConfigItem(
		keyName = "token",
		name = "Device token",
		description = "Made on Ironwise's Live data page (Connect the Ironwise plugin). It can only send data, and you can remove it there.",
		secret = true,
		position = 2
	)
	default String token()
	{
		return "";
	}

	String SYNC_COLLECTION_LOG = "syncCollectionLog";

	@ConfigItem(
		keyName = SYNC_COLLECTION_LOG,
		name = "Sync collection log",
		description = "Reads your collection log when you click Search in it (and the pages you open), and new collection log items from chat, and sends them to Ironwise, while Sync with Ironwise is ticked. To sync your whole log, tick this, open the collection log and click Search.",
		position = 3
	)
	default boolean syncCollectionLog()
	{
		return false;
	}

	@ConfigItem(
		keyName = "chatMessages",
		name = "Chat messages",
		description = "Say in the chat box when syncing starts working, why it stopped, and when it has read your collection log.",
		position = 4
	)
	default boolean chatMessages()
	{
		return true;
	}

	String SHOW_NEXT_STEP = "showNextStep";

	@ConfigItem(
		keyName = SHOW_NEXT_STEP,
		name = "Show next guide step",
		description = "Shows your next step in the BRUHsailer guide (Ironwise's Quests page) in a box on the game screen, while Sync with Ironwise is ticked. Shift + right-click the box to mark the step done, skip it, or Hide the box (Hide unticks this setting; tick it again to bring the box back). Drag it with Alt held to move it.",
		position = 5
	)
	default boolean showNextStep()
	{
		return true;
	}
}

package com.ironwise;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Deque;
import java.util.List;
import java.util.function.Predicate;
import javax.inject.Inject;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.MenuAction;
import net.runelite.client.config.RuneScapeProfileType;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.ComponentConstants;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;

/**
 * The Next step box (new in 0.4.0): the account's next BRUHsailer guide step, as Ironwise sent it.
 * Information only. Its menu entries are RuneLite overlay entries (Shift + right-click on the box):
 * two tell Ironwise the step is done or skipped, and Hide (0.4.1) turns the box off in the plugin's
 * settings. Nothing here acts in the game.
 */
class NextStepOverlay extends OverlayPanel
{
	static final String TARGET = "Next step";
	static final String MARK_DONE = "Mark step done";
	static final String SKIP = "Skip step";
	static final String HIDE = "Hide";
	/** What Hide says in chat: the only way back is the setting, so it names it. */
	static final String HIDDEN = "Ironwise: Next step box hidden. Tick Show next guide step in the Ironwise settings to bring it back.";
	static final int WIDTH = 200;
	/** The step's text (Ironwise's short summary of it). */
	static final int TEXT_LINES = 3;
	/** Where the step is in the guide, muted. */
	static final int PLACE_LINES = 1;
	static final String ELLIPSIS = "\u2026";
	/** Left off the end of a line before the ellipsis, so it never reads "Lumbridge \u00B7..." or "then,...". */
	private static final String TRAILING = " \u00B7,;:";
	private static final Color MUTED = new Color(160, 160, 160);

	private final Client client;
	private final IronwiseConfig config;
	private final GuideState guide;

	@Inject
	NextStepOverlay(IronwisePlugin plugin, Client client, IronwiseConfig config, GuideState guide)
	{
		super(plugin);
		this.client = client;
		this.config = config;
		this.guide = guide;
		setPosition(OverlayPosition.TOP_RIGHT);
		addMenuEntry(MenuAction.RUNELITE_OVERLAY, MARK_DONE, TARGET, e -> plugin.guideAction(GuideClient.DONE));
		addMenuEntry(MenuAction.RUNELITE_OVERLAY, SKIP, TARGET, e -> plugin.guideAction(GuideClient.SKIP));
		addMenuEntry(MenuAction.RUNELITE_OVERLAY, HIDE, TARGET, e -> plugin.hideNextStep());
	}

	/** Writes one of the plugin's settings: RuneLite's ConfigManager in the game, a stand-in in tests. */
	interface Settings
	{
		void set(String group, String key, boolean value);
	}

	/**
	 * Hide: unticks Show next guide step, which hides the box at once, and says in chat how to bring it
	 * back. The player asked for it, so the line shows even with chat messages off. Only the setting
	 * changes: nothing goes to Ironwise and nothing happens in the game.
	 */
	static void hide(Settings settings, Client client)
	{
		settings.set(IronwiseConfig.GROUP, IronwiseConfig.SHOW_NEXT_STEP, false);
		client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", HIDDEN, null);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		NextStep step = guide.step();
		if (step == null || !config.showNextStep() || !config.syncEnabled()
			|| client.getGameState() != GameState.LOGGED_IN
			|| RuneScapeProfileType.getCurrent(client) != RuneScapeProfileType.STANDARD)
		{
			return null;
		}

		// The player can resize the box; wrap to whatever width it has.
		Dimension size = getPreferredSize();
		int width = size != null && size.width > 0 ? size.width : WIDTH;
		panelComponent.setPreferredSize(new Dimension(width, 0));
		FontMetrics metrics = graphics.getFontMetrics();
		int inner = width - 2 * ComponentConstants.STANDARD_BORDER;
		Predicate<String> fits = s -> metrics.stringWidth(s) <= inner;

		panelComponent.getChildren().add(TitleComponent.builder()
			.text(step.behind ? "Next step (skipped)" : "Next step")
			.build());
		panelComponent.getChildren().add(LineComponent.builder()
			.left("Step " + step.n + " of " + step.total)
			.build());
		for (String line : wrap(step.text, TEXT_LINES, fits))
		{
			panelComponent.getChildren().add(LineComponent.builder().left(line).build());
		}
		for (String line : wrap(place(step), PLACE_LINES, fits))
		{
			panelComponent.getChildren().add(LineComponent.builder().left(line).leftColor(MUTED).build());
		}
		return super.render(graphics);
	}

	/**
	 * Where the step is: Ironwise's "Ch 2 \u00B7 2.2" when it sends one, otherwise (an older Ironwise) the
	 * chapter and section titles joined by a middle dot, leaving out whichever is blank.
	 */
	static String place(NextStep step)
	{
		if (step.where != null && !step.where.isEmpty())
		{
			return step.where;
		}
		if (step.chapter.isEmpty())
		{
			return step.section;
		}
		return step.section.isEmpty() ? step.chapter : step.chapter + " \u00B7 " + step.section;
	}

	/**
	 * Word-wraps {@code text} into at most {@code maxLines} lines that each pass {@code fits}; if it
	 * doesn't all fit, the last line ends with "...". A word too long for a line is broken.
	 */
	static List<String> wrap(String text, int maxLines, Predicate<String> fits)
	{
		List<String> lines = new ArrayList<>();
		if (text == null || text.trim().isEmpty() || maxLines < 1)
		{
			return lines;
		}
		Deque<String> words = new ArrayDeque<>(Arrays.asList(text.trim().split("\\s+")));
		String line = "";
		while (!words.isEmpty())
		{
			String word = words.peekFirst();
			if (word.isEmpty())
			{
				words.pollFirst();
				continue;
			}
			String longer = line.isEmpty() ? word : line + " " + word;
			if (fits.test(longer))
			{
				line = longer;
				words.pollFirst();
				continue;
			}
			if (line.isEmpty())
			{
				// One word wider than the box: as much of it as fits (at least one character).
				int cut = 1;
				while (cut < word.length() - 1 && fits.test(word.substring(0, cut + 1)))
				{
					cut++;
				}
				line = word.substring(0, cut);
				words.pollFirst();
				if (cut < word.length())
				{
					words.addFirst(word.substring(cut));
				}
			}
			if (words.isEmpty())
			{
				break;
			}
			// The line is full and there's more to come.
			if (lines.size() == maxLines - 1)
			{
				lines.add(ellipsize(line, fits));
				return lines;
			}
			lines.add(line);
			line = "";
		}
		if (!line.isEmpty())
		{
			lines.add(line);
		}
		return lines;
	}

	/** The line with "..." on the end, shortened until it fits, and no separator just before the "...". */
	static String ellipsize(String line, Predicate<String> fits)
	{
		String s = stripTrailing(line);
		while (!s.isEmpty() && !fits.test(s + ELLIPSIS))
		{
			s = stripTrailing(s.substring(0, s.length() - 1));
		}
		return s + ELLIPSIS;
	}

	/** Without spaces, middle dots, commas, semicolons or colons at the end. */
	private static String stripTrailing(String s)
	{
		int end = s.length();
		while (end > 0 && TRAILING.indexOf(s.charAt(end - 1)) >= 0)
		{
			end--;
		}
		return s.substring(0, end);
	}
}

package com.ironwise;

import com.google.gson.Gson;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonPrimitive;
import java.util.regex.Pattern;

/**
 * The account's next step in the BRUHsailer guide, as Ironwise works it out (new in 0.4.0). It comes
 * in the "guide" field of a sync answer and the "next" field of a /api/guide/tick answer. Ironwise
 * decides everything; the plugin only shows it.
 */
final class NextStep
{
	static final int MAX_TEXT = 240;
	private static final int MAX_PLACE = 100;
	private static final int MAX_STEPS = 100_000;
	private static final Pattern STEP_ID = Pattern.compile("^[0-9a-f]{16}(-\\d{1,6})?$");
	/** Colour tags would recolour the overlay's text; nothing from the guide should. */
	private static final Pattern COL_TAG = Pattern.compile("</?col(=[^>]*)?>", Pattern.CASE_INSENSITIVE);

	/** "main" or "landlubber". */
	final String variant;
	final String stepId;
	/** 1-based position in the guide. */
	final int n;
	final int total;
	final String chapter;
	final String section;
	/**
	 * Where the step is in the guide, as Ironwise writes it: "Ch 2 \u00B7 2.2" for the second section of
	 * the second chapter (new in 0.4.1). Null from an Ironwise that doesn't send it.
	 */
	final String where;
	final String text;
	/** Steps done so far. */
	final int done;
	/** A step Ironwise thinks you skipped earlier (every later step is done). */
	final boolean behind;

	NextStep(String variant, String stepId, int n, int total, String chapter, String section, String where, String text, int done, boolean behind)
	{
		this.variant = variant;
		this.stepId = stepId;
		this.n = n;
		this.total = total;
		this.chapter = chapter;
		this.section = section;
		this.where = where;
		this.text = text;
		this.done = done;
		this.behind = behind;
	}

	/** What an answer said about the guide. */
	static final class Reply
	{
		/** The answer had no such field: keep whatever is shown. */
		static final Reply NOTHING = new Reply(false, null);

		final boolean said;
		/** The step to show, or null for none (the field was null or unusable). */
		final NextStep step;

		private Reply(boolean said, NextStep step)
		{
			this.said = said;
			this.step = step;
		}
	}

	/** The step in field {@code key} of an Ironwise JSON answer. Never throws. */
	static Reply fromBody(Gson gson, String body, String key)
	{
		JsonObject object;
		try
		{
			object = gson.fromJson(body, JsonObject.class);
		}
		catch (RuntimeException e)
		{
			return Reply.NOTHING;
		}
		if (object == null || !object.has(key))
		{
			return Reply.NOTHING;
		}
		return new Reply(true, parse(object.get(key)));
	}

	/** A step from its JSON, or null if anything about it is missing or out of range. */
	static NextStep parse(JsonElement json)
	{
		if (json == null || !json.isJsonObject())
		{
			return null;
		}
		JsonObject o = json.getAsJsonObject();
		String variant = string(o, "variant");
		String stepId = string(o, "stepId");
		String state = string(o, "state");
		Integer n = integer(o, "n");
		Integer total = integer(o, "total");
		Integer done = integer(o, "done");
		String chapter = string(o, "chapter");
		String section = string(o, "section");
		String text = string(o, "text");
		if (!"main".equals(variant) && !"landlubber".equals(variant))
		{
			return null;
		}
		if (stepId == null || !STEP_ID.matcher(stepId).matches())
		{
			return null;
		}
		if (!"todo".equals(state) && !"behind".equals(state))
		{
			return null;
		}
		if (n == null || total == null || done == null || n < 1 || total < n || total > MAX_STEPS || done < 0 || done > total)
		{
			return null;
		}
		if (chapter == null || section == null || text == null)
		{
			return null;
		}
		text = clean(text, MAX_TEXT);
		if (text.isEmpty())
		{
			return null;
		}
		return new NextStep(variant, stepId, n, total, clean(chapter, MAX_PLACE), clean(section, MAX_PLACE),
			where(o), text, done, "behind".equals(state));
	}

	/** The optional "where": left out, null, blank or not text all mean none (the step still shows). */
	private static String where(JsonObject o)
	{
		String where = string(o, "where");
		if (where == null)
		{
			return null;
		}
		where = clean(where, MAX_PLACE);
		return where.isEmpty() ? null : where;
	}

	/**
	 * Plain one-line text the game's fonts can draw: no control characters or colour tags, curly quotes
	 * and dashes as plain ones (RuneLite's regular font has no curly quotes), single spaces, at most
	 * {@code max} characters.
	 */
	static String clean(String s, int max)
	{
		StringBuilder b = new StringBuilder(s.length());
		for (int i = 0; i < s.length(); i++)
		{
			char c = s.charAt(i);
			switch (c)
			{
				case '\u2018':
				case '\u2019':
				case '\u201A':
				case '\u201B':
				case '\u2032':
					b.append('\'');
					break;
				case '\u201C':
				case '\u201D':
				case '\u201E':
				case '\u2033':
					b.append('"');
					break;
				case '\u2010':
				case '\u2011':
				case '\u2012':
				case '\u2013':
				case '\u2212':
				case '\u2022':
					b.append('-');
					break;
				case '\u2192':
					b.append("->");
					break;
				case '\u2190':
					b.append("<-");
					break;
				case '\u2265':
					b.append(">=");
					break;
				case '\u2264':
					b.append("<=");
					break;
				default:
					if (Character.isISOControl(c) || Character.isWhitespace(c) || Character.isSpaceChar(c))
					{
						b.append(' ');
					}
					else if (Character.isSurrogate(c) || Character.getType(c) == Character.FORMAT)
					{
						// Emoji and invisible formatting characters: nothing the game's fonts can draw.
					}
					else
					{
						b.append(c);
					}
			}
		}
		String out = COL_TAG.matcher(b).replaceAll("").replaceAll(" {2,}", " ").trim();
		return out.length() <= max ? out : out.substring(0, max - 1).trim() + "\u2026";
	}

	private static String string(JsonObject o, String key)
	{
		JsonElement e = o.get(key);
		return e != null && e.isJsonPrimitive() && e.getAsJsonPrimitive().isString() ? e.getAsString() : null;
	}

	private static Integer integer(JsonObject o, String key)
	{
		JsonElement e = o.get(key);
		if (e == null || !e.isJsonPrimitive())
		{
			return null;
		}
		JsonPrimitive p = e.getAsJsonPrimitive();
		if (!p.isNumber())
		{
			return null;
		}
		double d = p.getAsDouble();
		if (d != Math.rint(d) || d < Integer.MIN_VALUE || d > Integer.MAX_VALUE)
		{
			return null;
		}
		return (int) d;
	}
}

package com.ironwise;

import com.google.gson.Gson;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.io.IOException;
import javax.inject.Inject;
import javax.inject.Singleton;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.HttpUrl;
import okhttp3.Response;

/**
 * "Mark step done" and "Skip step" from the Next step box: one POST to Ironwise's /api/guide/tick
 * on OkHttp's thread pool, with the same client and token as syncing (new in 0.4.0).
 */
@Singleton
class GuideClient
{
	static final String DONE = "done";
	static final String SKIP = "skip";

	static final String NOT_SYNCED = "Ironwise hasn't had a sync of this account from this device yet.";
	static final String NO_GUIDE = "this Ironwise app can't mark guide steps.";

	interface Listener
	{
		void done(Result result);
	}

	static final class Result
	{
		final boolean ok;
		/** Why it didn't work (when not ok). */
		final String message;
		/** The step after this one; null when there's none (or when not ok). */
		final NextStep next;

		private Result(boolean ok, String message, NextStep next)
		{
			this.ok = ok;
			this.message = message;
			this.next = next;
		}

		static Result failed(String message)
		{
			return new Result(false, message, null);
		}
	}

	private final SyncClient syncClient;
	private final Gson gson;

	@Inject
	GuideClient(SyncClient syncClient, Gson gson)
	{
		this.syncClient = syncClient;
		this.gson = gson;
	}

	static HttpUrl tickUrl(String address)
	{
		return SyncClient.appUrl(address, "/api/guide/tick");
	}

	/** The body Ironwise expects: {accountHash, stepId, action}. The hash is a string, as in syncs. */
	String body(GuideState.Tick tick)
	{
		JsonObject o = new JsonObject();
		o.addProperty("accountHash", tick.accountHash);
		o.addProperty("stepId", tick.stepId);
		o.addProperty("action", tick.action);
		return gson.toJson(o);
	}

	void send(HttpUrl url, String token, GuideState.Tick tick, Listener listener)
	{
		// The sync's client: redirects aren't followed, so the token only goes to the address the player set.
		syncClient.http.newCall(SyncClient.post(url, token, body(tick))).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				listener.done(Result.failed("can't reach the app (" + e.getMessage() + ")"));
			}

			@Override
			public void onResponse(Call call, Response response)
			{
				Result r;
				try
				{
					r = result(response.code(), SyncClient.bodyOf(response));
				}
				catch (IOException e)
				{
					r = Result.failed("couldn't read the app's answer (" + e.getMessage() + ")");
				}
				catch (RuntimeException e)
				{
					r = Result.failed("unexpected answer from the app");
				}
				finally
				{
					response.close();
				}
				listener.done(r);
			}
		});
	}

	Result result(int code, String body)
	{
		JsonObject answer = ironwise(body);
		String message = messageOf(answer);
		if (code >= 200 && code < 300)
		{
			if (answer == null || !isTrue(answer.get("ok")))
			{
				return Result.failed(SyncClient.NOT_IRONWISE);
			}
			// No "next" (or one Ironwise's plugin can't read): there's no step to show after this one.
			return new Result(true, null, NextStep.parse(answer.get("next")));
		}
		if (code >= 300 && code < 400)
		{
			return Result.failed("that address redirects somewhere else. Use the app's main address.");
		}
		if (code == 401 || code == 403)
		{
			if (answer == null)
			{
				return Result.failed(SyncClient.LOGIN);
			}
			return Result.failed(message != null ? message : code == 401 ? SyncClient.BAD_TOKEN : NOT_SYNCED);
		}
		if (code == 404)
		{
			return Result.failed(message != null ? message : NO_GUIDE);
		}
		return Result.failed(message != null ? message : "the app answered " + code);
	}

	/** Ironwise's JSON answer ({"ok": ...}), or null if the body is something else. */
	private JsonObject ironwise(String body)
	{
		try
		{
			JsonObject o = gson.fromJson(body, JsonObject.class);
			JsonElement ok = o == null ? null : o.get("ok");
			return ok != null && ok.isJsonPrimitive() && ok.getAsJsonPrimitive().isBoolean() ? o : null;
		}
		catch (RuntimeException e)
		{
			return null;
		}
	}

	private static boolean isTrue(JsonElement e)
	{
		return e != null && e.isJsonPrimitive() && e.getAsJsonPrimitive().isBoolean() && e.getAsBoolean();
	}

	private static String messageOf(JsonObject answer)
	{
		JsonElement m = answer == null ? null : answer.get("message");
		if (m == null || !m.isJsonPrimitive() || !m.getAsJsonPrimitive().isString())
		{
			return null;
		}
		String s = NextStep.clean(m.getAsString(), 200);
		return s.isEmpty() ? null : s;
	}
}

package com.ironwise;

import java.util.List;
import java.util.Map;

/**
 * What the plugin posts to Ironwise's /api/sync (version 1). Serialised with RuneLite's Gson, so
 * field names are the JSON names. The account hash is a string: it doesn't fit in a JSON number.
 */
class SyncPayload
{
	static final int VERSION = 1;

	final int v = VERSION;
	String plugin;
	long sentAt;
	Account account;
	/** RuneLite skill name → level and XP. */
	Map<String, SkillEntry> skills;
	Quests quests;
	/** "bank", "inventory", "equipment", "seedVault", "lootingBag", "groupStorage" → items. */
	Map<String, Container> containers;
	/** Varbit id → value. */
	Map<String, Integer> varbits;
	/** Varp id → value. */
	Map<String, Integer> varps;
	/** RuneLite config group ("timetracking", "killcount", "kingdomofmiscellania") → key → value. */
	Map<String, Map<String, String>> saved;
	/**
	 * The collection log as far as it's been seen this session (new in 0.3.0). Left out (null) until
	 * something is known, so older Ironwise apps, which ignore keys they don't know, are unaffected.
	 */
	CollectionLog collectionLog;

	static class Account
	{
		final String hash;
		final String rsn;
		final int world;

		Account(String hash, String rsn, int world)
		{
			this.hash = hash;
			this.rsn = rsn;
			this.world = world;
		}
	}

	static class SkillEntry
	{
		final int level;
		final int xp;

		SkillEntry(int level, int xp)
		{
			this.level = level;
			this.xp = xp;
		}
	}

	static class Quests
	{
		final int points;
		final List<QuestEntry> entries;

		Quests(int points, List<QuestEntry> entries)
		{
			this.points = points;
			this.entries = entries;
		}
	}

	static class QuestEntry
	{
		/** RuneLite's Quest enum name, e.g. "DRAGON_SLAYER_I". */
		final String id;
		final String name;
		/** NOT_STARTED, IN_PROGRESS or FINISHED. */
		final String state;

		QuestEntry(String id, String name, String state)
		{
			this.id = id;
			this.name = name;
			this.state = state;
		}
	}

	static class Container
	{
		/** When the game last sent this container (epoch ms). */
		final long seenAt;
		/** [item id, quantity] pairs. */
		final List<int[]> items;

		Container(long seenAt, List<int[]> items)
		{
			this.seenAt = seenAt;
			this.items = items;
		}
	}

	static class CollectionLog
	{
		/** From a search listing: every obtained item in the log. Left out until the player searches. */
		final ClogSnapshot all;
		/** Page name → the page as last viewed. */
		final Map<String, ClogPage> pages;
		/** ["item name", epoch ms] from "New item added to your collection log" since the last sync that got through. */
		final List<Object[]> added;

		CollectionLog(ClogSnapshot all, Map<String, ClogPage> pages, List<Object[]> added)
		{
			this.all = all;
			this.pages = pages;
			this.added = added;
		}
	}

	static class ClogSnapshot
	{
		/** When the listing was read (epoch ms). */
		final long seenAt;
		/** [item id, count] pairs, obtained items only. */
		final List<int[]> items;

		ClogSnapshot(long seenAt, List<int[]> items)
		{
			this.seenAt = seenAt;
			this.items = items;
		}
	}

	static class ClogPage
	{
		/** When the page was first seen, or last seen with something new on it (epoch ms). */
		final long seenAt;
		/** ["Vorkath kills", 123] pairs: the page's kill count lines. */
		final List<Object[]> kc;
		/** [item id, count] pairs, obtained items only. */
		final List<int[]> items;

		ClogPage(long seenAt, List<Object[]> kc, List<int[]> items)
		{
			this.seenAt = seenAt;
			this.kc = kc;
			this.items = items;
		}
	}
}

package com.ironwise;

import javax.inject.Singleton;

/**
 * The guide step shown in the Next step box, and the one "Mark step done"/"Skip step" at a time.
 * Answers that belong to an earlier account or login are dropped, and so is a sync answer that may
 * have been worked out before the latest mark reached Ironwise.
 */
@Singleton
class GuideState
{
	/** One "Mark step done" or "Skip step" on its way to Ironwise. */
	static final class Tick
	{
		final int session;
		final String accountHash;
		final String stepId;
		/** "done" or "skip". */
		final String action;

		Tick(int session, String accountHash, String stepId, String action)
		{
			this.session = session;
			this.accountHash = accountHash;
			this.stepId = stepId;
			this.action = action;
		}
	}

	private NextStep step;
	/** The account the step belongs to. */
	private String accountHash;
	/** Changes when the account changes or the player logs out, so late answers can't show another account's step. */
	private int session;
	private boolean ticking;
	/** When Ironwise last answered a mark (plugin clock); 0 if not this session. */
	private long tickAnsweredAt;

	synchronized NextStep step()
	{
		return step;
	}

	synchronized int session()
	{
		return session;
	}

	/** Forget the step (logout, another account, plugin stopped). */
	synchronized void clear()
	{
		step = null;
		accountHash = null;
		session++;
		ticking = false;
		tickAnsweredAt = 0;
	}

	/**
	 * A sync that got through. {@code sentAt} is when it was sent: a sync sent before the last mark
	 * was answered may have been worked out before the mark, so the mark's answer stays.
	 */
	synchronized void synced(int session, String accountHash, long sentAt, NextStep.Reply reply)
	{
		if (session != this.session || !reply.said || sentAt < tickAnsweredAt)
		{
			return;
		}
		this.step = reply.step;
		this.accountHash = accountHash;
	}

	/** Starts marking the step shown; null if nothing is shown or a mark is already on its way. */
	synchronized Tick startTick(String action)
	{
		if (ticking || step == null || accountHash == null)
		{
			return null;
		}
		ticking = true;
		return new Tick(session, accountHash, step.stepId, action);
	}

	/**
	 * Ironwise's answer to a mark: when it went through, its next step (null: none) replaces the one
	 * shown. False if the answer is for an earlier account or login, and was dropped.
	 */
	synchronized boolean ticked(Tick tick, long now, boolean ok, NextStep next)
	{
		if (tick.session != session)
		{
			return false;
		}
		ticking = false;
		if (ok)
		{
			step = next;
			tickAnsweredAt = now;
		}
		return true;
	}
}

package com.ironwise;

import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.EnumComposition;
import net.runelite.api.ScriptEvent;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.ScriptPreFired;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.config.RuneScapeProfileType;

/**
 * Reads the player's own collection log while they look at it, only when they've asked for it: the
 * Sync collection log setting (off by default), while Sync with Ironwise is ticked. Otherwise nothing
 * about the log is read, and anything read earlier this session is dropped so it's never sent. It only
 * watches what the game draws: no clicks, no menu actions, no scripts run, nothing added to the log's
 * interface. Everything here runs on the client thread.
 *
 * Two ways the game shows the log:
 * - A page (e.g. "Vorkath"): its name, "Obtained: x/y" and kill count lines in the heading
 *   (InterfaceID.Collection.HEADER_TEXT), and one item graphic per log slot in ITEMS_CONTENTS, drawn
 *   see-through unless obtained (clientscript proc collection_draw_log, 2732).
 * - The log's own Search: the server sends every obtained item through clientscript 4100,
 *   collection_delayed_transmit(obj, count, int, struct), one call per item. WikiSync (weirdgloop/WikiSync
 *   1ff4ea0, BSD-2) reads the item from argument 1, and RuneProfile (ReinhardtR/runeprofile-plugin 7c6ef18)
 *   and Temple OSRS (SMaloney2017/Temple-OSRS-Plugin d5de3a3) read the item and count from arguments 1
 *   and 2 (argument 0 is the script id). Script names and signatures: Joshua-F/cs2-scripts.
 */
@Singleton
class CollectionLogReader
{
	/** Clientscript collection_delayed_transmit: one call per obtained item while the log's Search lists them. */
	static final int COLLECTION_DELAYED_TRANSMIT = 4100;
	/**
	 * Enum log item → the version the log shows for the other body type, used when
	 * COLLECTION_PLAYER_BODYTYPE is 1 (collection_draw_log and collection_search_display_item). Ironwise
	 * turns them back into the log's own item ids.
	 */
	private static final int BODY_TYPE_ITEMS_ENUM = 2108;
	/**
	 * A search listing is finished once no item has arrived for this many ticks (large logs arrive over
	 * a few ticks: Temple OSRS waits 3 ticks, WikiSync 2).
	 */
	private static final int SEARCH_SETTLE_TICKS = 3;

	private final Client client;
	private final CollectionLogState state;
	private final IronwiseConfig config;

	/** Items from a search listing still arriving, or null. */
	private Map<Integer, Integer> listing;
	private int lastItemTick;
	/** How many items the last finished listing had, until the plugin has said so in chat. */
	private int finishedListing = -1;
	/** The page on screen last tick: a page only counts once it reads the same twice in a row. */
	private Page lastPage;
	private Map<Integer, Integer> bodyTypeItems;

	/** A page as drawn. */
	private static final class Page
	{
		final String name;
		final Map<String, Integer> kc;
		final List<Integer> shown;
		final Map<Integer, Integer> obtained;

		Page(String name, Map<String, Integer> kc, List<Integer> shown, Map<Integer, Integer> obtained)
		{
			this.name = name;
			this.kc = kc;
			this.shown = shown;
			this.obtained = obtained;
		}

		@Override
		public boolean equals(Object o)
		{
			if (!(o instanceof Page))
			{
				return false;
			}
			Page p = (Page) o;
			return name.equals(p.name) && kc.equals(p.kc) && shown.equals(p.shown) && obtained.equals(p.obtained);
		}

		@Override
		public int hashCode()
		{
			return Objects.hash(name, kc, shown, obtained);
		}
	}

	@Inject
	CollectionLogReader(Client client, CollectionLogState state, IronwiseConfig config)
	{
		this.client = client;
		this.state = state;
		this.config = config;
	}

	/** Logged out, hopping or a new account: drop anything half-read. */
	void reset()
	{
		listing = null;
		lastPage = null;
		finishedListing = -1;
	}

	/** The player has ticked Sync collection log, and Sync with Ironwise (the log is only read to be sent). */
	private boolean wanted()
	{
		return config.syncEnabled() && config.syncCollectionLog();
	}

	/**
	 * Whether the log may be read now, checked before every read. If not, everything read of it this
	 * session, half-read or not, is dropped at once. The plugin runs {@link #onGameTick} before it builds
	 * each sync, so once the setting is unticked no sync has a collection log section (Ironwise keeps
	 * what it had, as for a player who never opened the log).
	 */
	private boolean reading()
	{
		if (wanted())
		{
			return true;
		}
		reset();
		state.reset();
		return false;
	}

	void onScriptPreFired(ScriptPreFired event)
	{
		if (event.getScriptId() != COLLECTION_DELAYED_TRANSMIT || !reading() || !ownLog())
		{
			return;
		}
		ScriptEvent script = event.getScriptEvent();
		Object[] args = script == null ? null : script.getArguments();
		if (args == null || args.length < 3 || !(args[1] instanceof Integer) || !(args[2] instanceof Integer))
		{
			return;
		}
		int id = logItemId((Integer) args[1]);
		int count = (Integer) args[2];
		if (listing == null)
		{
			listing = new HashMap<>();
		}
		lastItemTick = client.getTickCount();
		if (id > 0 && count > 0)
		{
			listing.merge(id, count, Math::max);
		}
	}

	/** A "New item added to your collection log" chat line; true if it's new. */
	boolean onChatMessage(ChatMessage message, long now)
	{
		if (message.getType() != ChatMessageType.GAMEMESSAGE || !reading() || !standardWorld())
		{
			return false;
		}
		String name = CollectionLogState.addedItemName(message.getMessage());
		return name != null && state.added(name, now);
	}

	/** Finishes a search listing and reads the page on screen; true if anything new was recorded. */
	boolean onGameTick(long now)
	{
		if (!reading())
		{
			return false;
		}
		boolean changed = false;
		if (listing != null && client.getTickCount() - lastItemTick >= SEARCH_SETTLE_TICKS)
		{
			Map<Integer, Integer> items = listing;
			listing = null;
			if (ownLog() && state.searchSeen(items, now))
			{
				changed = true;
				finishedListing = items.size();
			}
		}
		Page page = pageOnScreen();
		if (page != null && page.equals(lastPage))
		{
			changed |= state.pageSeen(page.name, page.kc, page.shown, page.obtained, now);
		}
		lastPage = page;
		return changed;
	}

	/** How many items the last search listing had, once; -1 if there's been none since. */
	int takeFinishedListing()
	{
		int n = finishedListing;
		finishedListing = -1;
		return n;
	}

	/** The collection log page on screen, or null if there isn't one (or it doesn't add up). */
	private Page pageOnScreen()
	{
		Widget heading = client.getWidget(InterfaceID.Collection.HEADER_TEXT);
		Widget slots = client.getWidget(InterfaceID.Collection.ITEMS_CONTENTS);
		if (heading == null || slots == null || heading.isHidden() || slots.isHidden() || !ownLog())
		{
			return null;
		}
		Widget search = client.getWidget(InterfaceID.Collection.CONTENT_SEARCH);
		if (search != null && !search.isHidden())
		{
			return null;
		}
		Widget[] lines = heading.getDynamicChildren();
		if (lines == null || lines.length < 2)
		{
			return null;
		}
		String name = CollectionLogState.pageName(lines[0].getText());
		if (name == null)
		{
			return null;
		}
		int[] counts = null;
		Map<String, Integer> kc = new LinkedHashMap<>();
		for (int i = 1; i < lines.length; i++)
		{
			String text = lines[i].getText();
			int[] obtainedLine = CollectionLogState.obtainedLine(text);
			if (obtainedLine != null)
			{
				counts = obtainedLine;
				continue;
			}
			Map.Entry<String, Integer> line = CollectionLogState.kcLine(text);
			if (line != null)
			{
				kc.put(line.getKey(), line.getValue());
			}
		}
		if (counts == null)
		{
			return null;
		}
		List<Integer> shown = new ArrayList<>();
		Map<Integer, Integer> obtained = new HashMap<>();
		Widget[] items = slots.getDynamicChildren();
		for (Widget slot : items == null ? new Widget[0] : items)
		{
			int id = slot.getItemId();
			if (id <= 0)
			{
				continue;
			}
			id = logItemId(id);
			shown.add(id);
			// Obtained slots are drawn solid, the rest see-through.
			if (slot.getOpacity() == 0 && slot.getItemQuantity() > 0)
			{
				obtained.merge(id, slot.getItemQuantity(), Math::max);
			}
		}
		// Only trust a page whose slots match its own "Obtained: x/y" line.
		if (shown.size() != counts[1] || obtained.size() != counts[0])
		{
			return null;
		}
		return new Page(name, kc, shown, obtained);
	}

	/** Not another player's log (the house's adventure log opens theirs), and not Leagues, Deadman or beta. */
	private boolean ownLog()
	{
		return client.getVarbitValue(VarbitID.COLLECTION_POH_HOST_BOOK_OPEN) != 1 && standardWorld();
	}

	private boolean standardWorld()
	{
		return RuneScapeProfileType.getCurrent(client) == RuneScapeProfileType.STANDARD;
	}

	/** The log's own item id for an item it may show as its other-body-type version. */
	private int logItemId(int id)
	{
		if (client.getVarbitValue(VarbitID.COLLECTION_PLAYER_BODYTYPE) != 1)
		{
			return id;
		}
		if (bodyTypeItems == null)
		{
			bodyTypeItems = new HashMap<>();
			EnumComposition e = client.getEnum(BODY_TYPE_ITEMS_ENUM);
			if (e != null)
			{
				int[] keys = e.getKeys();
				int[] values = e.getIntVals();
				for (int i = 0; i < Math.min(keys.length, values.length); i++)
				{
					bodyTypeItems.put(values[i], keys[i]);
				}
			}
			bodyTypeItems = Collections.unmodifiableMap(bodyTypeItems);
		}
		return bodyTypeItems.getOrDefault(id, id);
	}
}

package com.ironwise;

import java.util.AbstractMap;
import java.util.ArrayList;
import java.util.Collection;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import javax.inject.Singleton;
import net.runelite.client.util.Text;

/**
 * What Ironwise has seen of the player's collection log this session, and how it goes into a sync.
 * It doesn't touch the game (CollectionLogReader does), so it can be unit tested.
 *
 * Collection log counts never go down, so a new reading of something already seen keeps the larger
 * count. That also stops a page drawn before the game sent its items (it shows 0) from undoing a good
 * reading.
 */
@Singleton
class CollectionLogState
{
	/** Caps, matched by the app's checks. */
	static final int MAX_ITEMS = 3000;
	static final int MAX_PAGES = 200;
	static final int MAX_ADDED = 100;
	static final int MAX_KC_LINES = 5;
	static final int MAX_NAME = 60;

	private static final Pattern ADDED = Pattern.compile("^New item added to your collection log: (.+)$");
	/** "Vorkath kills: 1,234" (a page's kill count lines, after removing colour tags). */
	private static final Pattern KC = Pattern.compile("^(.+?):\\s*([0-9][0-9,]*)$");
	/** "Obtained: 3/12" (the line under a page's name). */
	private static final Pattern OBTAINED = Pattern.compile("^Obtained:\\s*([0-9]+)/([0-9]+)$");

	/** A search listing: every obtained item in the log, or null until the player has searched this session. */
	private TreeMap<Integer, Integer> all;
	private long allSeenAt;
	/** Page name → the page as viewed, in the order first seen. */
	private final Map<String, Page> pages = new LinkedHashMap<>();
	/** "New item added" chat lines not yet carried by a sync that got through. */
	private final List<Added> added = new ArrayList<>();

	private static final class Page
	{
		long seenAt;
		final Map<String, Integer> kc = new LinkedHashMap<>();
		final TreeMap<Integer, Integer> items = new TreeMap<>();

		Page(long seenAt)
		{
			this.seenAt = seenAt;
		}
	}

	private static final class Added
	{
		final String name;
		final long at;

		Added(String name, long at)
		{
			this.name = name;
			this.at = at;
		}
	}

	/** A new account (or the plugin restarting): forget everything. */
	void reset()
	{
		all = null;
		allSeenAt = 0;
		pages.clear();
		added.clear();
	}

	/**
	 * A finished search listing (item id → count). The listing covers the whole log, so it's recorded
	 * as seen now even when nothing changed. False if it's too big to send.
	 */
	boolean searchSeen(Map<Integer, Integer> items, long now)
	{
		if (items.size() > MAX_ITEMS)
		{
			return false;
		}
		if (all == null)
		{
			all = new TreeMap<>();
		}
		mergeMax(all, items);
		allSeenAt = now;
		return true;
	}

	/**
	 * A page as viewed: its name, kill count lines, the item ids it shows and the ones drawn as
	 * obtained (id → count). An item a search listing earlier this session had counts too. True if
	 * the page is new or something on it went up.
	 */
	boolean pageSeen(String name, Map<String, Integer> kc, Collection<Integer> shown, Map<Integer, Integer> obtained, long now)
	{
		Map<Integer, Integer> items = new TreeMap<>(obtained);
		if (all != null)
		{
			for (int id : shown)
			{
				Integer n = all.get(id);
				if (n != null)
				{
					items.merge(id, n, Math::max);
				}
			}
		}
		if (items.size() > MAX_ITEMS)
		{
			return false;
		}
		Page page = pages.get(name);
		boolean isNew = page == null;
		if (isNew)
		{
			if (pages.size() >= MAX_PAGES)
			{
				evictOldestPage();
			}
			page = new Page(now);
			pages.put(name, page);
		}
		boolean changed = mergeMax(page.items, items);
		for (Map.Entry<String, Integer> line : kc.entrySet())
		{
			Integer old = page.kc.get(line.getKey());
			if (line.getValue() <= 0 || (old == null && page.kc.size() >= MAX_KC_LINES))
			{
				continue;
			}
			if (old == null || line.getValue() > old)
			{
				page.kc.put(line.getKey(), line.getValue());
				changed = true;
			}
		}
		if (changed)
		{
			page.seenAt = now;
		}
		return isNew || changed;
	}

	/** A "New item added to your collection log" line. False if that item is already waiting to be sent. */
	boolean added(String name, long at)
	{
		for (Added a : added)
		{
			if (a.name.equals(name))
			{
				return false;
			}
		}
		if (added.size() >= MAX_ADDED)
		{
			added.remove(0);
		}
		added.add(new Added(name, at));
		return true;
	}

	/** A sync carrying these "added" entries got through: drop them (ones that arrived since stay). */
	void addedSent(List<Object[]> sent)
	{
		if (sent == null)
		{
			return;
		}
		for (Object[] s : sent)
		{
			added.removeIf(a -> a.name.equals(s[0]) && Long.valueOf(a.at).equals(s[1]));
		}
	}

	/** The section for a sync, or null while nothing is known. */
	SyncPayload.CollectionLog toPayload()
	{
		if (all == null && pages.isEmpty() && added.isEmpty())
		{
			return null;
		}
		SyncPayload.ClogSnapshot snapshot = all == null ? null : new SyncPayload.ClogSnapshot(allSeenAt, pairs(all));
		Map<String, SyncPayload.ClogPage> pageOut = new LinkedHashMap<>();
		for (Map.Entry<String, Page> e : pages.entrySet())
		{
			Page p = e.getValue();
			List<Object[]> kc = new ArrayList<>();
			for (Map.Entry<String, Integer> line : p.kc.entrySet())
			{
				kc.add(new Object[]{line.getKey(), line.getValue()});
			}
			pageOut.put(e.getKey(), new SyncPayload.ClogPage(p.seenAt, kc, pairs(p.items)));
		}
		List<Object[]> addedOut = new ArrayList<>();
		for (Added a : added)
		{
			addedOut.add(new Object[]{a.name, a.at});
		}
		return new SyncPayload.CollectionLog(snapshot, pageOut, addedOut);
	}

	private void evictOldestPage()
	{
		String oldest = null;
		long oldestAt = Long.MAX_VALUE;
		for (Map.Entry<String, Page> e : pages.entrySet())
		{
			if (e.getValue().seenAt < oldestAt)
			{
				oldest = e.getKey();
				oldestAt = e.getValue().seenAt;
			}
		}
		pages.remove(oldest);
	}

	/** Adds each positive count, keeping the larger one; true if anything was added or went up. */
	private static boolean mergeMax(Map<Integer, Integer> into, Map<Integer, Integer> from)
	{
		boolean changed = false;
		for (Map.Entry<Integer, Integer> e : from.entrySet())
		{
			int id = e.getKey();
			int qty = e.getValue();
			if (id <= 0 || qty <= 0)
			{
				continue;
			}
			Integer old = into.get(id);
			if (old == null && into.size() >= MAX_ITEMS)
			{
				continue;
			}
			if (old == null || qty > old)
			{
				into.put(id, qty);
				changed = true;
			}
		}
		return changed;
	}

	private static List<int[]> pairs(Map<Integer, Integer> items)
	{
		List<int[]> out = new ArrayList<>(items.size());
		for (Map.Entry<Integer, Integer> e : items.entrySet())
		{
			out.add(new int[]{e.getKey(), e.getValue()});
		}
		return out;
	}

	/** Game text without colour tags and with ordinary spaces. */
	static String plain(String text)
	{
		return text == null ? "" : Text.removeTags(text).replace('\u00A0', ' ').trim();
	}

	/** The item named in a "New item added to your collection log: …" chat line, or null. */
	static String addedItemName(String message)
	{
		Matcher m = ADDED.matcher(plain(message));
		if (!m.matches())
		{
			return null;
		}
		String name = m.group(1).trim();
		return name.isEmpty() || name.length() > MAX_NAME ? null : name;
	}

	/** A page's name from its heading, or null if it's empty or too long. */
	static String pageName(String heading)
	{
		String name = plain(heading);
		return name.isEmpty() || name.length() > MAX_NAME ? null : name;
	}

	/**
	 * A kill count line ("Vorkath kills: 1,234") as its label and count, or null if it isn't one. A count
	 * of 0 is left out: it says nothing the app needs, and every number Ironwise sends is then positive.
	 */
	static Map.Entry<String, Integer> kcLine(String text)
	{
		Matcher m = KC.matcher(plain(text));
		if (!m.matches())
		{
			return null;
		}
		String label = m.group(1).trim();
		String digits = m.group(2).replace(",", "");
		if (label.isEmpty() || label.length() > MAX_NAME || label.equalsIgnoreCase("Obtained") || digits.length() > 10)
		{
			return null;
		}
		long n = Long.parseLong(digits);
		if (n <= 0 || n > Integer.MAX_VALUE)
		{
			return null;
		}
		return new AbstractMap.SimpleImmutableEntry<>(label, (int) n);
	}

	/** The "Obtained: 3/12" line as {obtained, total}, or null if it isn't that line. */
	static int[] obtainedLine(String text)
	{
		Matcher m = OBTAINED.matcher(plain(text));
		if (!m.matches() || m.group(1).length() > 6 || m.group(2).length() > 6)
		{
			return null;
		}
		return new int[]{Integer.parseInt(m.group(1)), Integer.parseInt(m.group(2))};
	}
}

package com.ironwise;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.Player;
import net.runelite.api.Quest;
import net.runelite.api.QuestState;
import net.runelite.api.Skill;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.client.config.ConfigManager;

/**
 * Reads the logged-in account into a {@link SyncPayload}. Everything here runs on the client thread.
 */
@Singleton
class PayloadBuilder
{
	/** RuneLite config groups forwarded as they are: Time Tracking, kill counts, Kingdom of Miscellania. */
	static final String[] SAVED_GROUPS = {"timetracking", "killcount", "kingdomofmiscellania"};
	private static final int MAX_SAVED_KEYS = 2000;
	/** Quest states come from client scripts, so they're re-read on login, when quest points change, and every 10 minutes. */
	private static final long QUESTS_EVERY_MS = 10 * 60_000L;

	/** Containers Ironwise reads, by game inventory id. */
	private static final Map<Integer, String> CONTAINERS = new LinkedHashMap<>();

	static
	{
		CONTAINERS.put(InventoryID.BANK, "bank");
		CONTAINERS.put(InventoryID.INV, "inventory");
		CONTAINERS.put(InventoryID.WORN, "equipment");
		CONTAINERS.put(InventoryID.SEED_VAULT, "seedVault");
		CONTAINERS.put(InventoryID.LOOTING_BAG, "lootingBag");
		CONTAINERS.put(InventoryID.INV_GROUP_TEMP, "groupStorage");
	}

	private final Client client;
	private final ConfigManager configManager;
	private final CollectionLogState collectionLog;

	/** When the game last sent each container this session (the bank only arrives when it's opened). */
	private final Map<Integer, Long> seenAt = new HashMap<>();
	/** The last copy of each container, for when the client no longer holds it. */
	private final Map<Integer, SyncPayload.Container> lastCopy = new HashMap<>();
	private SyncPayload.Quests quests;
	private long questsReadAt;
	private boolean questsStale = true;

	@Inject
	PayloadBuilder(Client client, ConfigManager configManager, CollectionLogState collectionLog)
	{
		this.client = client;
		this.configManager = configManager;
		this.collectionLog = collectionLog;
	}

	static boolean isTrackedContainer(int containerId)
	{
		return CONTAINERS.containsKey(containerId);
	}

	/** A new account (or the plugin restarting): forget this session's containers, quests and collection log. */
	void reset()
	{
		seenAt.clear();
		lastCopy.clear();
		quests = null;
		questsStale = true;
		collectionLog.reset();
	}

	void questsChanged()
	{
		questsStale = true;
	}

	void onContainerChanged(int containerId, ItemContainer container, long now)
	{
		if (!CONTAINERS.containsKey(containerId) || container == null)
		{
			return;
		}
		seenAt.put(containerId, now);
		lastCopy.put(containerId, copy(container, now));
	}

	/** The account as it is now, or null if the player isn't fully logged in yet. */
	SyncPayload build(String version, long now)
	{
		Player player = client.getLocalPlayer();
		long hash = client.getAccountHash();
		if (player == null || player.getName() == null || hash == -1)
		{
			return null;
		}

		SyncPayload p = new SyncPayload();
		p.plugin = version;
		p.sentAt = now;
		p.account = new SyncPayload.Account(Long.toString(hash), player.getName(), client.getWorld());
		p.skills = skills();
		p.quests = quests(now);
		p.containers = containers(now);
		p.varbits = new LinkedHashMap<>();
		for (int id : TrackedVars.VARBITS)
		{
			p.varbits.put(Integer.toString(id), client.getVarbitValue(id));
		}
		p.varps = new LinkedHashMap<>();
		for (int id : TrackedVars.VARPS)
		{
			p.varps.put(Integer.toString(id), client.getVarpValue(id));
		}
		p.saved = saved();
		p.collectionLog = collectionLog.toPayload();
		return p;
	}

	private Map<String, SyncPayload.SkillEntry> skills()
	{
		Map<String, SyncPayload.SkillEntry> out = new LinkedHashMap<>();
		for (Skill skill : Skill.values())
		{
			if (skill == null || "Overall".equals(skill.getName()))
			{
				continue;
			}
			out.put(skill.getName(), new SyncPayload.SkillEntry(client.getRealSkillLevel(skill), client.getSkillExperience(skill)));
		}
		return out;
	}

	private SyncPayload.Quests quests(long now)
	{
		if (quests != null && !questsStale && now - questsReadAt < QUESTS_EVERY_MS)
		{
			return quests;
		}
		List<SyncPayload.QuestEntry> entries = new ArrayList<>();
		for (Quest quest : Quest.values())
		{
			QuestState state;
			try
			{
				state = quest.getState(client);
			}
			catch (RuntimeException e)
			{
				// A quest whose script fails is left out; Ironwise treats it as unknown.
				continue;
			}
			if (state != null)
			{
				entries.add(new SyncPayload.QuestEntry(quest.name(), quest.getName(), state.name()));
			}
		}
		quests = new SyncPayload.Quests(client.getVarpValue(VarPlayerID.QP), entries);
		questsReadAt = now;
		questsStale = false;
		return quests;
	}

	private Map<String, SyncPayload.Container> containers(long now)
	{
		Map<String, SyncPayload.Container> out = new LinkedHashMap<>();
		for (Map.Entry<Integer, String> e : CONTAINERS.entrySet())
		{
			int id = e.getKey();
			ItemContainer live = client.getItemContainer(id);
			if (live != null)
			{
				out.put(e.getValue(), copy(live, seenAt.getOrDefault(id, now)));
			}
			else if (lastCopy.containsKey(id))
			{
				out.put(e.getValue(), lastCopy.get(id));
			}
		}
		return out;
	}

	private static SyncPayload.Container copy(ItemContainer container, long seen)
	{
		List<int[]> items = new ArrayList<>();
		for (Item item : container.getItems())
		{
			// Skips empty slots and bank placeholders.
			if (item != null && item.getId() > 0 && item.getQuantity() > 0)
			{
				items.add(new int[]{item.getId(), item.getQuantity()});
			}
		}
		return new SyncPayload.Container(seen, items);
	}

	private Map<String, Map<String, String>> saved()
	{
		Map<String, Map<String, String>> out = new LinkedHashMap<>();
		String profile = configManager.getRSProfileKey();
		if (profile == null)
		{
			return out;
		}
		for (String group : SAVED_GROUPS)
		{
			Map<String, String> values = new LinkedHashMap<>();
			for (String key : configManager.getRSProfileConfigurationKeys(group, profile, ""))
			{
				if (values.size() >= MAX_SAVED_KEYS)
				{
					break;
				}
				String value = configManager.getConfiguration(group, profile, key);
				if (value != null)
				{
					values.put(key, value);
				}
			}
			if (!values.isEmpty())
			{
				out.put(group, values);
			}
		}
		return out;
	}
}
